    LspReferenceRead = { bg = c.elevated },
    LspReferenceWrite = { bg = c.elevated, bold = true },
    LspInlayHint = { fg = c.muted, bg = c.surface },
    LspCodeLens = { fg = c.muted, italic = true },
    LspCodeLensSeparator = { fg = c.subtle },
    LspSignatureActiveParameter = { fg = c.yellow, bold = true },

    TelescopeNormal = { fg = c.fg, bg = c.surface },
