  local links = {
    lCursor = "Cursor",
    CursorIM = "Cursor",
    VisualNOS = "Visual",
    LineNrAbove = "LineNr",
    LineNrBelow = "LineNr",
    CursorLineSign = "SignColumn",
    CursorLineFold = "FoldColumn",
    VertSplit = "WinSeparator",
    StatusLineTerm = "StatusLine",
    StatusLineTermNC = "StatusLineNC",
    PmenuKind = "Pmenu",
    PmenuKindSel = "PmenuSel",
    PmenuExtra = "Pmenu",
    PmenuExtraSel = "PmenuSel",
    PmenuBorder = "FloatBorder",
    Conditional = "Statement",
    Repeat = "Statement",
    Label = "Statement",
    Exception = "Statement",
    Include = "PreProc",
    Define = "PreProc",
    Macro = "PreProc",
    PreCondit = "PreProc",
    StorageClass = "Type",
    Structure = "Type",
    Typedef = "Type",
    Tag = "Special",
    SpecialChar = "Special",
    SpecialComment = "Comment",
    Debug = "Special",
    ["@constant"] = "Constant",
    ["@constant.builtin"] = "Constant",
    ["@constant.macro"] = "Macro",
    ["@module.builtin"] = "Special",
    ["@label"] = "Label",
    ["@string"] = "String",
    ["@string.documentation"] = "String",
    ["@string.special"] = "SpecialChar",
    ["@string.special.url"] = "Underlined",
    ["@character"] = "Character",
    ["@character.special"] = "SpecialChar",
    ["@boolean"] = "Boolean",
    ["@number"] = "Number",
    ["@number.float"] = "Float",
    ["@type"] = "Type",
    ["@type.builtin"] = "Type",
    ["@type.definition"] = "Typedef",
    ["@attribute"] = "PreProc",
    ["@attribute.builtin"] = "PreProc",
    ["@property"] = "@variable.member",
    ["@function"] = "Function",
    ["@function.builtin"] = "Function",
    ["@function.call"] = "Function",
    ["@function.macro"] = "Macro",
    ["@function.method"] = "Function",
    ["@function.method.call"] = "Function",
    ["@constructor"] = "Type",
    ["@operator"] = "Operator",
    ["@keyword"] = "Keyword",
    ["@punctuation.special"] = "Special",
    ["@comment"] = "Comment",
    ["@comment.documentation"] = "Comment",
    ["@comment.error"] = "DiagnosticError",
    ["@comment.warning"] = "DiagnosticWarn",
    ["@comment.todo"] = "Todo",
    ["@comment.note"] = "DiagnosticInfo",
    ["@tag"] = "Tag",
    ["@tag.builtin"] = "Tag",
    ["@tag.attribute"] = "@property",
    ["@tag.delimiter"] = "Delimiter",
    ["@diff.plus"] = "Added",
    ["@diff.minus"] = "Removed",
    ["@diff.delta"] = "Changed",
    LspReferenceTarget = "LspReferenceText",
    TelescopePromptNormal = "TelescopeNormal",
    TelescopePromptBorder = "TelescopeBorder",
    TelescopePromptTitle = "TelescopeTitle",
    TelescopeResultsNormal = "TelescopeNormal",
    TelescopeResultsBorder = "TelescopeBorder",
    TelescopeResultsTitle = "TelescopeTitle",
    TelescopePreviewNormal = "TelescopeNormal",
    TelescopePreviewBorder = "TelescopeBorder",
    TelescopePreviewTitle = "TelescopeTitle",
    GitSignsAddNr = "GitSignsAdd",
    GitSignsChangeNr = "GitSignsChange",
    GitSignsDeleteNr = "GitSignsDelete",
    GitSignsChangedelete = "GitSignsChange",
    GitSignsTopdelete = "GitSignsDelete",
    GitSignsUntracked = "GitSignsAdd",
    GitSignsAddInline = "DiffAdd",
    GitSignsChangeInline = "DiffText",
    GitSignsDeleteInline = "DiffDelete",
    CmpItemAbbrMatchFuzzy = "CmpItemAbbrMatch",
    CmpGhostText = "BlinkCmpGhostText",
    BlinkCmpMenu = "Pmenu",
    BlinkCmpMenuBorder = "FloatBorder",
    BlinkCmpMenuSelection = "PmenuSel",
    BlinkCmpScrollBarThumb = "PmenuThumb",
    BlinkCmpScrollBarGutter = "PmenuSbar",
    BlinkCmpDoc = "NormalFloat",
    BlinkCmpDocBorder = "FloatBorder",
    BlinkCmpDocSeparator = "WinSeparator",
    BlinkCmpSignatureHelp = "NormalFloat",
    BlinkCmpSignatureHelpBorder = "FloatBorder",
    BlinkCmpSignatureHelpActiveParameter = "LspSignatureActiveParameter",
  }

  local semantic = {
    namespace = "@module",
    type = "@type",
    class = "@type",
    enum = "@type",
    interface = "@type",
    struct = "@type",
    typeParameter = "@type",
    parameter = "@variable.parameter",
    variable = "@variable",
    property = "@property",
    enumMember = "@constant",
    event = "@type",
    ["function"] = "@function",
    method = "@function.method",
    macro = "@function.macro",
    keyword = "@keyword",
    modifier = "@keyword",
    comment = "@comment",
    string = "@string",
    number = "@number",
    regexp = "@string.regexp",
    operator = "@operator",
    decorator = "@attribute",
  }
  for token, target in pairs(semantic) do
    links["@lsp.type." .. token] = target
  end
  links["@lsp.typemod.variable.readonly"] = "@constant"
  links["@lsp.typemod.variable.defaultLibrary"] = "@variable.builtin"
  links["@lsp.typemod.function.defaultLibrary"] = "@function.builtin"

  for severity, spec in pairs({
    Error = { c.red, c.delete },
    Warn = { c.yellow, c.warning },
    Info = { c.blue, c.change },
    Hint = { c.cyan, c.info },
    Ok = { c.green, c.add },
  }) do
    h["Diagnostic" .. severity] = { fg = spec[1] }
    h["DiagnosticVirtualText" .. severity] = { fg = spec[1], bg = spec[2] }
    h["DiagnosticUnderline" .. severity] = { sp = spec[1], undercurl = true }
    for _, prefix in ipairs({ "Sign", "Floating", "VirtualLines" }) do
      links["Diagnostic" .. prefix .. severity] = "Diagnostic" .. severity
    end
  end
  h.DiagnosticUnnecessary = { fg = c.muted }
  h.DiagnosticDeprecated = { strikethrough = true, sp = c.red }

  local kinds = {
    Text = "String",
    Method = "Function",
    Function = "Function",
    Constructor = "Type",
    Field = "@property",
    Variable = "Identifier",
    Class = "Type",
    Interface = "Type",
    Module = "@module",
    Property = "@property",
    Unit = "Number",
    Value = "Constant",
    Enum = "Type",
    Keyword = "Keyword",
    Snippet = "Special",
    Color = "Special",
    File = "Directory",
    Reference = "Underlined",
    Folder = "Directory",
    EnumMember = "Constant",
    Constant = "Constant",
    Struct = "Type",
    Event = "Type",
    Operator = "Operator",
    TypeParameter = "Type",
  }
  for kind, target in pairs(kinds) do
    links["CmpItemKind" .. kind] = target
    links["BlinkCmpKind" .. kind] = target
  end
  for group, target in pairs(links) do
    h[group] = { link = target }
  end
  return h
end

return M
